export enum Kind {
	// UI control messages.
	CAPTURE_USER_EVENTS = 'bridge::capture_user_events',
	RELEASE_USER_EVENTS = 'bridge::release_user_events',
	CLOSE_APP           = 'bridge::close_app',
	DISABLE_TILE        = 'bridge::disable_tile',
	ENABLE_TILE         = 'bridge::enable_tile',
	HIDE_TILE           = 'bridge::hide_tile',
	SHOW_TILE           = 'bridge::show_tile',
	PUSH_NOTIFICATION   = 'bridge::push_notification',
	SET_BADGE_COUNT     = 'bridge::set_badge_count',

	// Data requests from apps.
	GET_BRIDGE_VERSION  = 'bridge::get_bridge_version',
	GET_OPEN_ENCOUNTER  = 'bridge::get_open_encounter',
	GET_PAGE            = 'bridge::get_page',
	GET_PATIENT_INFO    = 'bridge::get_patient',
	GET_PLATFORM        = 'bridge::get_platform',

	// Bridge-pushed data.
	SET_OPEN_ENCOUNTER  = 'bridge::set_open_encounter',
	SET_PATIENT_INFO    = 'bridge::set_patient',

	DEPRECATED_GET_AUTH_USER = 'bridge::get_auth_user',
}

export const MAGIC_VALUE = 'BRIDGE_EVENT' // used for basic/preliminary filtering of messages

// ── V1 ───────────────────────────────────────────────────────────────────────────────────────────────────────────────

export type V1Message = {
	event: Kind
	eventType: typeof MAGIC_VALUE
	data?: unknown
}

export type V1AppMessage = V1Message & {
	appId: string
	sdkVersion: string
}

// ── V2 ───────────────────────────────────────────────────────────────────────────────────────────────────────────────

// App ─> Bridge request and response
export type V2AppRequest = {
	v: 2
	magicValue: typeof MAGIC_VALUE
	sdkVersion: string

	id: number
	kind: Kind
	data?: unknown
}

export type V2BridgeResponse = {
	v: 2
	magicValue: typeof MAGIC_VALUE
	bridgeVersion: string

	respId: number
	data?: unknown
}

// Bridge ─> App request and response
export type V2BridgeRequest = {
	v: 2
	magicValue: typeof MAGIC_VALUE
	bridgeVersion: string

	id: number
	kind: Kind
	data?: unknown
}

