import { Kind, MAGIC_VALUE, V2AppRequest, V2BridgeRequest, V2BridgeResponse } from './types'

import version from '../version'

let msgId = 0
const awaitingResp = new Map<number, (data?: unknown) => void>()
let bridgeReqHandler: (kind: Kind, data?: unknown) => void
export function setBridgeReqHandler(handler: (kind: Kind, data?: unknown) => void) { bridgeReqHandler = handler }

export function send(kind: Kind, data?: unknown) {
	_send(msgId++, kind, data)
}

export function sendAwaitResp<U>(kind: Kind, data?: unknown, timeoutMs=5000): Promise<U> {
	const id = msgId++

	return new Promise((resolve, reject) => {
		const timer = setTimeout(() => {
			awaitingResp.delete(id)
			reject(new Error(`timeout waiting for ${kind} response (v2) from Bridge`))
		}, timeoutMs)
		const cb = (data?: unknown) => {
			clearTimeout(timer)
			awaitingResp.delete(id)
			resolve(data as U)
		}

		awaitingResp.set(id, cb)

		_send(id, kind, data)
	})
}

function _send(id: number, kind: Kind, data?: unknown) {
	const msg: V2AppRequest = {
		v: 2,
		magicValue: MAGIC_VALUE,

		id,
		kind,
		data,
		sdkVersion: version,
	}
	window.parent.postMessage(msg, '*')
}

export function asMessage(msg: unknown): V2BridgeRequest | V2BridgeResponse | undefined {
	const msgAsV2 = msg as V2BridgeRequest | V2BridgeResponse
	if (msgAsV2?.v !== 2 || msgAsV2.magicValue !== MAGIC_VALUE) {
		return // not a V2 message
	}
	return msgAsV2
}

export function handleMessage(msg: V2BridgeRequest | V2BridgeResponse) {
	// Bridge ─> App requests
	if ('id' in msg) {
		bridgeReqHandler?.(msg.kind, msg.data)
		return
	}

	// Response to App ─> Bridge request
	if ('respId' in msg) {
		awaitingResp.get(msg.respId)?.(msg.data)
		return
	}
}
