import bus from '//libs/ts/common/bus'

import { Kind } from './types'
import * as v1 from './v1'
import * as v2 from './v2'
export { Kind }

v1.setBridgeReqHandler((kind, data) => bus.emit(kind, data))
v2.setBridgeReqHandler((kind, data) => bus.emit(kind, data))

// Version to use for sending messages. Default to V1 unless V2 is detected.
let v: (typeof v1 | typeof v2)= v1

// Lightweight probe for V2. A V2-compatible Bridge will respond.
v2.send(Kind.GET_PLATFORM)

/**
 * Sends a message without waiting for a response.
 */
export function send(kind: Kind, data?: unknown) {
	v.send(kind, data)
}

/**
 * Sends a message and awaits a response within `timeoutMs` milliseconds (default 5000, probably overkill).
 */
export async function sendAwaitResp<U>(kind: Kind, data?: unknown, timeoutMs=5000): Promise<U> {
	return v.sendAwaitResp<U>(kind, data, timeoutMs)
}

window.addEventListener('message', (ev: MessageEvent<unknown>) => {
	if (ev.source !== window.parent) {
		return // incoming messages always come through proxy
	}

	const asV1 = v1.asMessage(ev.data)
	if (asV1) {
		return v1.handleMessage(asV1)
	}

	const asV2 = v2.asMessage(ev.data)
	if (asV2) {
		v = v2 // upon detection of V2-compatibility, upgrade to V2.
		return v2.handleMessage(asV2)
	}
})
